create table public.named_payroll_permissions (user_id uuid not null references public.user_profiles(id) on delete cascade,permission text not null check(permission like 'finance.payroll.%'),primary key(user_id,permission));
alter table public.named_payroll_permissions enable row level security;
revoke all on public.named_payroll_permissions from anon,authenticated,public;
grant select on public.named_payroll_permissions to authenticated,service_role;
create policy "Read own designated payroll tasks" on public.named_payroll_permissions for select to authenticated using (user_id=(select auth.uid()) and public.dashboard_has_active_profile());
insert into public.named_payroll_permissions select person,task from unnest(array['2954e9e7-9b8a-4ed3-a624-71f91c36d2c3'::uuid,'300385cb-de78-4bb5-9670-d8245f87aecf'::uuid]) person cross join unnest(array['finance.payroll.comparison.view','finance.payroll.dentrix_ascend.view','finance.payroll.gusto.contractors.view','finance.payroll.gusto.employees.view','finance.payroll.gusto.overview.view','finance.payroll.gusto.payroll_runs.view','finance.payroll.gusto.view','finance.payroll.provider_compensation.view','finance.payroll.view']) task;
create function private.dashboard_designated_payroll_reader() returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.named_payroll_permissions r join public.user_profiles p on p.id=r.user_id where p.id=(select auth.uid()) and p.is_active and p.is_approved and p.status='Active' and r.permission='finance.payroll.view')
$$;
revoke all on function private.dashboard_designated_payroll_reader() from public,anon;
grant execute on function private.dashboard_designated_payroll_reader() to authenticated;
revoke select on public.gusto_benefit_plans from anon;
create policy "Active payroll readers only" on public.gusto_benefit_plans as restrictive for select to authenticated using (public.dashboard_has_active_profile() and (public.is_admin_or_above() or private.dashboard_designated_payroll_reader()));
create policy "Designated payroll review" on public.gusto_benefit_plans for select to authenticated using (private.dashboard_designated_payroll_reader());
